import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from psr ----
// Stand-in for the 1968 PSR B1919+21 radio observations plotted on the cover of Joy
// Division's Unknown Pleasures: 80 successive pulse periods, 300 samples each, 92 ms wide.
// Seeded synthesis, NOT the real Cambridge recording.

const ROWS = 80;
const COLS = 300;
const SAMPLE_MS = 92 / (COLS - 1);

function mulberry32(seed: number): () => number {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = mulberry32(0x1919);

// Arrival time and pulse energy both wander slowly between periods, so strong pulses
// arrive in runs rather than scattered one to a row.
let centre = 150;
let energy = 0.45;

const pulsar: number[][] = Array.from({ length: ROWS }, () => {
  centre = 150 + 0.85 * (centre - 150) + (random() - 0.5) * 14;
  // Mean-reverting so the walk cannot park at an extreme and leave a run of dead rows.
  energy = Math.min(1, Math.max(0.02, 0.45 + 0.55 * (energy - 0.45) + (random() - 0.5) * 0.55));

  const amplitude = 10 + 65 * Math.pow(energy, 1.6);
  const spread = 5 + 9 * random();
  const level = -1 + 0.7 * random();
  const echo = amplitude * 0.35 * random();
  let drift = 0;

  return Array.from({ length: COLS }, (_, col) => {
    drift = drift * 0.86 + (random() - 0.5) * 0.5; // correlated receiver noise
    const main = (col - centre) / spread;
    const trail = (col - centre - spread * 1.6) / (spread * 1.3);
    return (
      level +
      drift * 2 +
      amplitude * Math.exp(-main * main) +
      echo * Math.exp(-trail * trail)
    );
  });
});

const sampleTime = (col: number): number => col * SAMPLE_MS;

const MARGIN = { top: 28, right: 14, bottom: 34, left: 14 };
// Each trace reaches this many row-steps above its own baseline, so a strong pulse
// covers roughly sixteen of the traces behind it.
const OVERLAP = 16;

const CAPTION = 'Synthetic data from a seeded generator, not the 1968 PSR B1919+21 recording.';

/** One row per pulse, each row a run of signal samples at the same fixed interval. */
export type Data = number[][];

export default function PsrB191921({ data = pulsar, width }: { data?: Data; width: number }) {
  const height = Math.round(width * 0.66);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const { traces, xTicks } = useMemo(() => {
    const x = d3
      .scaleLinear()
      .domain([0, sampleTime(data[0].length - 1)])
      .range([0, innerWidth]);

    const [lo, hi] = d3.extent(data.flat()) as [number, number];

    // A tall pulse in one of the first rows would climb out of the frame. Its reach, in
    // row-steps, is fixed by the data, so the exact reserve above row 0 is closed-form.
    const reach = data.map((row, i) => (((d3.max(row) ?? lo) - lo) / (hi - lo)) * OVERLAP - i);
    const steps = Math.max(0, ...reach);
    const reserve = (steps * innerHeight) / (data.length - 1 + steps);

    const z = d3
      .scalePoint<number>()
      .domain(data.map((_, i) => i))
      .range([reserve, innerHeight]);

    const y = d3.scaleLinear().domain([lo, hi]).range([0, -OVERLAP * z.step()]);

    const area = d3
      .area<number>()
      .x((_, i) => x(sampleTime(i)))
      .y0(0)
      .y1((d) => y(d));
    const line = d3
      .line<number>()
      .x((_, i) => x(sampleTime(i)))
      .y((d) => y(d));

    return {
      traces: data.map((row, i) => ({
        key: i,
        offset: z(i) ?? 0,
        fill: area(row) ?? undefined,
        stroke: line(row) ?? undefined
      })),
      xTicks: x.ticks(Math.max(2, Math.round(innerWidth / 90))).map(
        (v, i): Tick => ({ value: i === 0 ? `${v} ms` : String(v), offset: x(v) })
      )
    };
  }, [data, innerWidth, innerHeight]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`Stacked ridgeline of 80 successive radio pulses from the pulsar PSR B1919+21, each trace filled opaquely so nearer traces occlude the ones behind. ${CAPTION}`}
    >
      <rect width={width} height={height} fill="var(--bg)" />
      <text x={MARGIN.left} y={16} fill="var(--muted)" fontSize={11}>
        {CAPTION}
      </text>

      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {/* Painted back to front: each opaque fill hides the traces already drawn above it. */}
        {traces.map((t) => (
          <g key={t.key} transform={`translate(0,${t.offset})`}>
            <path d={t.fill} fill="var(--bg)" />
            <path d={t.stroke} fill="none" stroke="var(--text)" strokeWidth={1} />
          </g>
        ))}
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
      </g>
    </svg>
  );
}
